-- name: by_schema
-- dialect: teradata
LOCKING ROW FOR ACCESS
SELECT TRIM(r.ChildDB) AS schema_name, TRIM(r.ChildDB) AS table_schema, TRIM(r.ChildTable) AS table_name, COALESCE(NULLIF(TRIM(r.IndexName), ''), 'FK_' || TRIM(r.ChildTable) || '_' || CAST(r.IndexID AS VARCHAR(12))) AS constraint_name, TRIM(r.ChildKeyColumn) AS column_name, TRIM(r.ParentDB) AS referenced_schema, TRIM(r.ParentDB) AS referenced_table_schema, TRIM(r.ParentTable) AS referenced_table, TRIM(r.ParentTable) AS referenced_table_name, TRIM(r.ParentKeyColumn) AS referenced_column, TRIM(r.ParentKeyColumn) AS referenced_column_name FROM DBC.All_RI_ChildrenV r LEFT JOIN DBC.ColumnsV c ON UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(r.ChildDB)) AND UPPER(TRIM(c.TableName)) = UPPER(TRIM(r.ChildTable)) AND UPPER(TRIM(c.ColumnName)) = UPPER(TRIM(r.ChildKeyColumn)) WHERE UPPER(TRIM(r.ChildDB)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(r.ChildDB)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS')  ORDER BY TRIM(r.ChildDB), TRIM(r.ChildTable), r.IndexID, COALESCE(c.ColumnId, 0), TRIM(r.ChildKeyColumn);

-- name: by_table
-- dialect: teradata
LOCKING ROW FOR ACCESS
SELECT TRIM(r.ChildDB) AS schema_name, TRIM(r.ChildDB) AS table_schema, TRIM(r.ChildTable) AS table_name, COALESCE(NULLIF(TRIM(r.IndexName), ''), 'FK_' || TRIM(r.ChildTable) || '_' || CAST(r.IndexID AS VARCHAR(12))) AS constraint_name, TRIM(r.ChildKeyColumn) AS column_name, TRIM(r.ParentDB) AS referenced_schema, TRIM(r.ParentDB) AS referenced_table_schema, TRIM(r.ParentTable) AS referenced_table, TRIM(r.ParentTable) AS referenced_table_name, TRIM(r.ParentKeyColumn) AS referenced_column, TRIM(r.ParentKeyColumn) AS referenced_column_name FROM DBC.All_RI_ChildrenV r LEFT JOIN DBC.ColumnsV c ON UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(r.ChildDB)) AND UPPER(TRIM(c.TableName)) = UPPER(TRIM(r.ChildTable)) AND UPPER(TRIM(c.ColumnName)) = UPPER(TRIM(r.ChildKeyColumn)) WHERE UPPER(TRIM(r.ChildDB)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(r.ChildDB)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS')  AND UPPER(TRIM(r.ChildTable)) = UPPER(TRIM(:table_name)) ORDER BY TRIM(r.ChildDB), TRIM(r.ChildTable), r.IndexID, COALESCE(c.ColumnId, 0), TRIM(r.ChildKeyColumn);
